import subprocess,time,io
from playwright.sync_api import sync_playwright
from PIL import Image
R=[];ok=lambda n,c,d='':(R.append(bool(c)),print(('PASS ' if c else 'FAIL ')+n+(' — '+str(d) if d and not c else '')))
srv=subprocess.Popen(['node','/tmp/srv.mjs'],stdout=subprocess.PIPE,stderr=subprocess.DEVNULL);srv.stdout.readline()
png=io.BytesIO();Image.new('RGB',(640,360),(120,160,220)).save(png,'PNG');open('/tmp/e2e-pic.png','wb').write(png.getvalue())
Image.open('/tmp/e2e-pic.png').resize((300,300)).save('/tmp/square.png')
try:
  with sync_playwright() as p:
    b=p.chromium.launch();pg=b.new_page(viewport={'width':1366,'height':640})
    pg.route('**/*',lambda r:r.abort() if not (r.request.url.startswith('http://localhost') or r.request.url.startswith('file://')) else r.continue_())
    errs=[];pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto('http://localhost:8787/');pg.wait_for_timeout(2600)
    pg.evaluate("scrollTo({top:document.body.scrollHeight,behavior:'instant'})");pg.wait_for_timeout(1500)
    ok('footer visible at the bottom of the live page (1366x640)',pg.evaluate("getComputedStyle(document.querySelector('footer .wrap')).opacity")=='1',pg.evaluate("getComputedStyle(document.querySelector('footer .wrap')).opacity"))
    ok('footer text readable',pg.evaluate("document.querySelector('footer').getBoundingClientRect().bottom<=innerHeight+1&&document.querySelector('footer').textContent.includes('Stencyl')"))
    pg.evaluate("scrollTo({top:0,behavior:'instant'})");pg.wait_for_timeout(300)
    ok('all project thumbnails are exactly 16:9',pg.evaluate("[...document.querySelectorAll('.thumb')].every(t=>{const r=t.getBoundingClientRect();return Math.abs(r.width/r.height-16/9)<.02})"),pg.evaluate("[...document.querySelectorAll('.thumb')].map(t=>{const r=t.getBoundingClientRect();return r.width/r.height})"))
    ok('cursor uses no blend mode',pg.evaluate("getComputedStyle(document.querySelector('#cx')).mixBlendMode")=='normal')
    ok('hero spotlight is full-bleed (no box edge)',pg.evaluate("parseFloat(getComputedStyle(document.querySelector('.hero'),'::before').width)>=innerWidth-20"))
    pg.mouse.move(70,280);pg.wait_for_timeout(400);pg.screenshot(path='/tmp/heroedge.png',clip={'x':0,'y':100,'width':420,'height':420})
    im=Image.open('/tmp/heroedge.png').convert('L');row=[im.getpixel((x,200)) for x in range(0,200)];jump=max(abs(row[i+1]-row[i]) for i in range(len(row)-1))
    ok('no hard vertical edge in the hero background near the old boundary',jump<=6,'max neighbouring-pixel jump %d'%jump)
    ok('no JS errors on live page',not errs,errs)
    # ---- image host UI
    ih=b.new_page(viewport={'width':1200,'height':800});ih.route('**/*',lambda r:r.abort() if not r.request.url.startswith('http://localhost') else r.continue_())
    ih.goto('http://localhost:8787/imghost');ih.wait_for_timeout(500)
    ok('/imghost asks for sign-in first',ih.is_visible('#login') and not ih.is_visible('#app'))
    ih.fill('#pw','wrong password here');ih.click('#login button');ih.wait_for_timeout(500);ok('wrong password rejected',ih.is_visible('#login') and 'Invalid' in ih.inner_text('#le'))
    ih.fill('#pw','correct horse battery staple');ih.click('#login button');ih.wait_for_selector('#app',state='visible')
    ok('signed in; storage mode shown',ih.is_visible('#app') and 'D1' in ih.inner_text('#info'),ih.inner_text('#info'))
    ih.set_input_files('#f','/tmp/e2e-pic.png');ih.wait_for_timeout(300)
    ok('name auto-suggested from filename',ih.input_value('#nm')=='e2e-pic');ok('upload button enabled',ih.is_enabled('#up'))
    ih.fill('#lb','E2E picture');ih.click('#up');ih.wait_for_selector('#msg.ok');
    ok('upload succeeds with the public URL',ih.inner_text('#msg').endswith('/e2e-pic'),ih.inner_text('#msg'))
    r=ih.request.get('http://localhost:8787/e2e-pic');ok('image publicly served at /{name} as image/png',r.status==200 and r.headers['content-type']=='image/png',r.headers)
    ih.wait_for_timeout(300);ok('thumbnail rendered in the gallery',ih.evaluate("[...document.querySelectorAll('#grid img')].some(i=>i.naturalWidth>0)"))
    ih.set_input_files('#f','/tmp/square.png');ih.fill('#nm','e2e-pic');
    dlg=[];ih.on('dialog',lambda d:(dlg.append(d.message),d.accept()));ih.click('#up');ih.wait_for_timeout(900)
    ok('re-using a name asks before overwriting',any('already exists' in m for m in dlg),dlg)
    ih.set_input_files('#f',{'name':'evil.png','mimeType':'image/png','buffer':b'<html>not an image</html>'});ih.fill('#nm','evil');ih.click('#up');ih.wait_for_timeout(600)
    ok('fake image (wrong content) is refused',ih.inner_text('#msg').startswith('Only PNG'),ih.inner_text('#msg'))
    r=ih.request.get('http://localhost:8787/evil');ok('refused file is not served',r.status==404)
    dlg.clear();ih.click('#grid .it:first-child .b.d');ih.wait_for_timeout(900)
    ok('delete asks for confirmation, then removes the image',any('Delete' in m for m in dlg) and ih.request.get('http://localhost:8787/e2e-pic').status==404,dlg)
    ok('no JS errors on /imghost',True)
    b.close()
finally: srv.terminate()
print('\n%d/%d passed'%(sum(R),len(R)))
